-- オトノフ: 評価・コメントのシード（サクラ含む）
-- 先に change_rating_criteria_4.sql と seed_indie_artists.sql を実行してください。
-- Supabase Dashboard → SQL Editor で実行。何度実行しても重複しません（ON CONFLICT DO NOTHING）。
-- 生成レビューは email が @otonofu-seed.local のダミーアカウントによるものです。

-- 必要拡張とカラムの保険
create extension if not exists pgcrypto;
alter table public.reviews add column if not exists session_opt_out boolean not null default false;
alter table public.reviews add column if not exists updated_at timestamptz default now();

-- 1) シード用ダミーアカウント（auth.users）。handle_new_user トリガでプロフィールも自動作成されます。
on conflict (id) do nothing;

-- 2) レビュー（歌詞・音楽性・雰囲気・革新性 / 総合はその平均）
on conflict (id) do nothing;

-- 3) サクラコメント（review_comments・匿名）
on conflict (id) do nothing;

-- 4) アルバム平均評価の再計算（保険。トリガがあれば挿入時に自動更新済み）
update public.albums al set
  avg_rating = coalesce((select round(avg(r.rating)::numeric,1) from public.reviews r
                          where r.album_id = al.id and r.user_id is not null), 0),
  rating_count = (select count(*)::integer from public.reviews r
                   where r.album_id = al.id and r.user_id is not null)
where al.id in (select distinct album_id from public.reviews where user_id is not null);
